let rec decode_check_value (csil_c : Cbor.t) : check_value =
  match csil_c with
  | Cbor.Array [ csil_idx; csil_v ] -> (match Cbor.to_i64 csil_idx with 0L -> Text (Cbor.to_text csil_v) | 1L -> Int (Cbor.to_i64 csil_v) | 2L -> Float (Cbor.to_float csil_v) | csil_n -> failwith (Printf.sprintf "csilgen: unknown union variant %Ld" csil_n))
  | _ -> failwith "csilgen: expected union array for check_value"

and decode_check_result (csil_c : Cbor.t) : check_result =
  match csil_c with
  | Cbor.Map csil_kvs ->
      let csil_field k = List.assoc_opt (Cbor.Text k) csil_kvs in
      let csil_req k =
        match csil_field k with Some v -> v | None -> failwith ("csilgen: missing field " ^ k)
      in
      ignore csil_req;
      {
        result = (Cbor.to_bool (csil_req "result"));
        entries = (match (csil_req "entries") with Cbor.Map csil_kvs -> List.map (fun (csil_k, csil_v) -> ((Cbor.to_text csil_k), (decode_check_value csil_v))) csil_kvs | _ -> failwith "csilgen: expected map");
      }
  | _ -> failwith "csilgen: expected map for check_result"

